type JsonResponse<T> = {
  status: number;
  body: T;
  headers: Headers;
};

const requestJsonAt = async <T>(
  rootUrl: string,
  path: string,
  init?: {
    method?: string;
    headers?: Record<string, string>;
    body?: unknown;
  }
): Promise<JsonResponse<T>> => {
  const response = await fetch(rootUrl + path, {
    method: init?.method ?? "GET",
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {})
    },
    body:
      init?.body === undefined ? undefined : JSON.stringify(init.body)
  });
  return {
    status: response.status,
    body: (await response.json()) as T,
    headers: response.headers
  };
};

const requestJson = async <T>(
  path: string,
  init?: {
    method?: string;
    headers?: Record<string, string>;
    body?: unknown;
  }
): Promise<JsonResponse<T>> => requestJsonAt<T>(baseUrl, path, init);

const completeRequiredAdminPasswordChangeAt = async (
  rootUrl: string,
  sessionToken: string,
  username: string,
  password: string
): Promise<string> => {
  const changedPassword = await requestJsonAt<{
    adminUser: { passwordChangeRequired: boolean };
    revokedAdminSessionIds: string[];
  }>(rootUrl, "/api/v1/admin/auth/password", {
    method: "POST",
    headers: { authorization: `Bearer ${sessionToken}` },
    body: { password }
  });
  assert.equal(changedPassword.status, 200);
  assert.equal(changedPassword.body.adminUser.passwordChangeRequired, false);
  assert.equal(changedPassword.body.revokedAdminSessionIds.length > 0, true);

  const signIn = await requestJsonAt<{
    adminUser: { passwordChangeRequired: boolean };
    sessionToken: string;
  }>(rootUrl, "/api/v1/admin/auth/sign-in", {
    method: "POST",
    body: { username, password }
  });
  assert.equal(signIn.status, 200);
  assert.equal(signIn.body.adminUser.passwordChangeRequired, false);
  return signIn.body.sessionToken;
};

const uploadMinimalOriginalUnitDependencies = async (
  tenantKey: string,
  workspaceKey: string,
  unitIds: readonly string[]
): Promise<void> => {
  for (const unitId of unitIds) {
    const upload = await requestJson(
      `/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/source-packages`,
      {
        method: "POST",
        body: {
          fileName: `compat-unit-${unitId.replaceAll(/[^a-zA-Z0-9.-]/g, "-")}.xml`,
          mediaType: "application/xml",
          sourceDocument: `<Unit><Metadata><Id>${unitId}</Id><Label>${unitId}</Label></Metadata><Definition player="">Compatibility fixture</Definition></Unit>`
        }
      }
    );
    assert.equal(upload.status, 201, unitId);
  }
};

