    if (fixture.encoding === "brotli-base64") {
      return Buffer.from(
        readBrotliBase64Fixture(
          resolve(originalTestcenterCorpusRoot, fixture.fixture)
        ),
        "utf8"
      );
    }
    const document = readFileSync(
      resolve(originalTestcenterCorpusRoot, fixture.fixture)
    );
