test("source document import extracts encoded IMS manifest from base64 ZIP packages", async () => {
  const tenantKey = "integration-tenant-zip-manifest";
  const workspaceKey = "integration-workspace-zip-manifest";

  await requestJson("/api/v1/platform/tenants", {
    method: "POST",
    body: { tenantKey, displayName: tenantKey }
  });
  await requestJson(`/api/v1/tenants/${tenantKey}/workspaces`, {
    method: "POST",
    body: { workspaceKey, displayName: workspaceKey }
  });

  const zipPayload = createZipBase64([
    {
      fileName: "README.txt",
      content: "not the manifest"
    },
    {
      fileName: "export/imsmanifest.xml",
      content: Buffer.concat([
        Buffer.from([0x00, 0x00, 0xfe, 0xff]),
        encodeUtf32(
          `<?xml version="1.0" encoding="ISO-10646-UCS-4"?>
          <manifest xmlns="http://www.imsglobal.org/xsd/imscp_v1p1">
            <organizations default="ORG-ZIP">
              <organization identifier="ORG-ZIP">
                <item identifierref="RES-ZIP-BOOKLET">
                  <title>ZIP Booklet</title>
                  <item identifierref="RES-ZIP-UNIT">
                    <title>ZIP Unit</title>
                  </item>
                </item>
              </organization>
            </organizations>
            <resources>
              <resource identifier="RES-ZIP-BOOKLET" href="booklets/zip-booklet.xml" />
              <resource identifier="RES-ZIP-UNIT" href="items/zip-unit.xml" />
            </resources>
          </manifest>`,
          "big-endian"
        )
      ])
    }
  ]);

  const sourcePackage = await requestJson<{
    sourcePackage: { sourcePackageId: string };
  }>(`/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/source-packages`, {
    method: "POST",
    body: {
      fileName: "testcenter-export.zip",
      mediaType: "application/zip",
      sourceDocument: `data:application/zip;base64,${zipPayload}`
    }
  });

  const importResult = await requestJson<{
    importJob: { status: string; diagnostics: Array<{ code: string }> };
    stagedContentRelease: { contentReleaseId: string } | null;
  }>(`/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/import-jobs`, {
    method: "POST",
    body: {
      sourcePackageId: sourcePackage.body.sourcePackage.sourcePackageId
    }
  });

  assert.equal(importResult.status, 201);
  assert.equal(importResult.body.importJob.status, "completed");
  assert.deepEqual(importResult.body.importJob.diagnostics, []);
  assert.ok(importResult.body.stagedContentRelease?.contentReleaseId);

  const contentRelease = await requestJson<{
    contentReleaseDetail: {
      contentRelease: {
        runtimeSnapshot: {
          bookletEntries: Array<{
            bookletKey: string;
            displayLabel: string;
            unitEntries: Array<{ unitKey: string; displayLabel: string }>;
          }>;
        };
      };
    };
  }>(
    `/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/content-releases/${importResult.body.stagedContentRelease.contentReleaseId}`
  );

  assert.equal(contentRelease.status, 200);
  assert.deepEqual(
    contentRelease.body.contentReleaseDetail.contentRelease.runtimeSnapshot,
    {
      bookletEntries: [
        {
          bookletKey: "booklets/zip-booklet.xml",
          displayLabel: "ZIP Booklet",
          unitEntries: [{ unitKey: "items/zip-unit.xml", displayLabel: "ZIP Unit" }]
        }
      ]
    }
  );

  const ebcdicZipPayload = createZipBase64([
    {
      fileName: "export/imsmanifest.xml",
      content: encodeIbm1141(
        `<?xml version="1.0" encoding="IBM01141"?>
        <manifest xmlns="http://www.imsglobal.org/xsd/imscp_v1p1">
          <organizations default="ORG-EBCDIC">
            <organization identifier="ORG-EBCDIC">
              <item identifierref="RES-EBCDIC-BOOKLET">
                <title>Prüfung Köln</title>
                <item identifierref="RES-EBCDIC-UNIT">
                  <title>Einheit Köln</title>
                </item>
              </item>
            </organization>
          </organizations>
          <resources>
            <resource identifier="RES-EBCDIC-BOOKLET" href="booklets/ebcdic-booklet.xml" />
            <resource identifier="RES-EBCDIC-UNIT" href="items/ebcdic-unit.xml" />
          </resources>
        </manifest>`
      )
    }
  ]);
  const ebcdicSourcePackage = await requestJson<{
    sourcePackage: { sourcePackageId: string };
  }>(`/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/source-packages`, {
    method: "POST",
    body: {
      fileName: "ebcdic-testcenter-export.zip",
      mediaType: "application/zip",
      sourceDocument: `data:application/zip;base64,${ebcdicZipPayload}`
    }
  });
  assert.equal(ebcdicSourcePackage.status, 201);
  const ebcdicImport = await requestJson<{
    importJob: { status: string; diagnostics: Array<{ code: string }> };
    stagedContentRelease: { contentReleaseId: string } | null;
  }>(`/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/import-jobs`, {
    method: "POST",
    body: {
      sourcePackageId: ebcdicSourcePackage.body.sourcePackage.sourcePackageId
    }
  });
  assert.equal(ebcdicImport.status, 201);
  assert.equal(ebcdicImport.body.importJob.status, "completed");
  assert.deepEqual(ebcdicImport.body.importJob.diagnostics, []);
  assert.ok(ebcdicImport.body.stagedContentRelease?.contentReleaseId);
  const ebcdicContentRelease = await requestJson<{
    contentReleaseDetail: {
      contentRelease: {
        runtimeSnapshot: {
          bookletEntries: Array<{
            bookletKey: string;
            displayLabel: string;
            unitEntries: Array<{ unitKey: string; displayLabel: string }>;
          }>;
        };
      };
    };
  }>(
    `/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/content-releases/${ebcdicImport.body.stagedContentRelease.contentReleaseId}`
  );
  assert.equal(ebcdicContentRelease.status, 200);
  assert.deepEqual(
    ebcdicContentRelease.body.contentReleaseDetail.contentRelease.runtimeSnapshot,
    {
      bookletEntries: [
        {
          bookletKey: "booklets/ebcdic-booklet.xml",
          displayLabel: "Prüfung Köln",
          unitEntries: [
            { unitKey: "items/ebcdic-unit.xml", displayLabel: "Einheit Köln" }
          ]
        }
      ]
    }
  );

  const mismatchedZipPayload = createZipBase64([
    {
      fileName: "imsmanifest.xml",
      content: Buffer.concat([
        Buffer.from([0x00, 0x00, 0xfe, 0xff]),
        encodeUtf32(
          `<?xml version="1.0" encoding="UTF-16"?>
          <manifest xmlns="http://www.imsglobal.org/xsd/imscp_v1p1">
            <organizations default="ORG-ZIP">
              <organization identifier="ORG-ZIP">
                <item identifierref="RES-ZIP-BOOKLET">
                  <title>ZIP Booklet</title>
                  <item identifierref="RES-ZIP-UNIT">
                    <title>ZIP Unit</title>
                  </item>
                </item>
              </organization>
            </organizations>
            <resources>
              <resource identifier="RES-ZIP-BOOKLET" href="booklets/zip-booklet.xml" />
              <resource identifier="RES-ZIP-UNIT" href="items/zip-unit.xml" />
            </resources>
          </manifest>`,
          "big-endian"
        )
      ])
    }
  ]);
  const mismatchedSourcePackage = await requestJson<{
    sourcePackage: { sourcePackageId: string };
  }>(`/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/source-packages`, {
    method: "POST",
    body: {
      fileName: "mismatched-testcenter-export.zip",
      mediaType: "application/zip",
      sourceDocument: `data:application/zip;base64,${mismatchedZipPayload}`
    }
  });
  assert.equal(mismatchedSourcePackage.status, 201);
  const mismatchedImport = await requestJson<{
    importJob: { status: string; diagnostics: Array<{ code: string }> };
    stagedContentRelease: null;
  }>(`/api/v1/tenants/${tenantKey}/workspaces/${workspaceKey}/import-jobs`, {
    method: "POST",
    body: {
      sourcePackageId:
        mismatchedSourcePackage.body.sourcePackage.sourcePackageId
    }
  });
  assert.equal(mismatchedImport.status, 201);
  assert.equal(mismatchedImport.body.importJob.status, "failed");
  assert.ok(
    mismatchedImport.body.importJob.diagnostics.some(
      diagnostic => diagnostic.code === "source_document_xml_encoding_mismatch"
    )
  );
  assert.equal(mismatchedImport.body.stagedContentRelease, null);
});

